#!/usr/bin/env node
/**
 * Phase 133 — Developer docs generator.
 *
 * Reads openapi.json (generated by Scramble) and produces a structured
 * developer guide as docs/api-reference.json, grouping endpoints by tag
 * and annotating them with their HTTP method, path, auth requirement,
 * and a one-line description.
 *
 * Usage:
 *   node scripts/generate-api-docs.mjs
 *   node scripts/generate-api-docs.mjs --spec=public/openapi.json --out=docs/api-reference.json
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root      = resolve(__dirname, '..');

// Parse CLI flags
const args = Object.fromEntries(
    process.argv.slice(2)
        .filter(a => a.startsWith('--'))
        .map(a => a.slice(2).split('='))
);

const specPath = resolve(root, args.spec ?? 'public/openapi.json');
const outPath  = resolve(root, args.out  ?? 'docs/api-reference.json');

if (!existsSync(specPath)) {
    console.error(`[ERROR] OpenAPI spec not found at: ${specPath}`);
    console.error('        Run: php artisan scramble:export --path=public/openapi.json');
    process.exit(1);
}

const spec = JSON.parse(readFileSync(specPath, 'utf8'));

// Group operations by tag
const byTag = {};

for (const [path, methods] of Object.entries(spec.paths ?? {})) {
    for (const [method, op] of Object.entries(methods)) {
        if (typeof op !== 'object') continue;

        const tags    = op.tags ?? ['Untagged'];
        const summary = op.summary ?? op.description ?? '';
        const auth    = (op.security && op.security.length > 0)
            ? op.security.map(s => Object.keys(s).join('+')).join(',')
            : (op['x-unauthenticated'] ? 'none' : 'unknown');

        for (const tag of tags) {
            if (!byTag[tag]) byTag[tag] = [];
            byTag[tag].push({
                method:      method.toUpperCase(),
                path,
                summary,
                auth,
                operationId: op.operationId ?? null,
                deprecated:  op.deprecated ?? false,
            });
        }
    }
}

// Build output document
const output = {
    generated_at: new Date().toISOString(),
    title:        spec.info?.title ?? 'API Reference',
    version:      spec.info?.version ?? 'unknown',
    total_paths:  Object.keys(spec.paths ?? {}).length,
    tags:         Object.keys(byTag).sort().map(tag => ({
        tag,
        count:      byTag[tag].length,
        endpoints:  byTag[tag].sort((a, b) => a.path.localeCompare(b.path)),
    })),
};

// Ensure output directory exists
const outDir = dirname(outPath);
if (!existsSync(outDir)) {
    mkdirSync(outDir, { recursive: true });
}

writeFileSync(outPath, JSON.stringify(output, null, 2));

console.log(`[OK] API reference written to: ${outPath}`);
console.log(`     ${output.total_paths} paths across ${output.tags.length} tags`);
